UNITS = [{"id": "PEDS-U041", "ch": 5, "n": 41, "title": "Incidence & Bilirubin Metabolism", "sec": "Neonatal Jaundice (Intro) · p21", "guide": "Incidence: seen in upto 60% newborns -> pathological 5-10% (require treatment), physiological majority (no treatment required). Bilirubin metabolism: breakdown of RBCs -> haem -> biliverdin -> unconjugated bilirubin (water insoluble) --UDPGT (uridine diphosphate glucuronyl transferase, in liver)--> conjugated bilirubin (water soluble) -> through bile duct -> intestines: stercobilinogen (in colon) 90% excreted in stools, urobilinogen 10% excreted in urine; enterohepatic circulation loops back. (Book p21)", "qs": ["PEDS-C5-001", "PEDS-C5-002", "PEDS-C5-003", "PEDS-C5-004", "PEDS-C5-005", "PEDS-C5-006", "PEDS-C5-007", "PEDS-C5-008", "PEDS-C5-009", "PEDS-C5-010", "PEDS-C5-011", "PEDS-C5-012", "PEDS-C5-013"]}, {"id": "PEDS-U042", "ch": 5, "n": 42, "title": "Assessment of Jaundice (Kramer & TcB)", "sec": "Assessment of Jaundice · p21-22", "guide": "1. Serum bilirubin levels: best investigation; value = total serum bilirubin (TSB) -> Direct = conjugated, Indirect = unconjugated. 2. Screening of baby: initial clinical assessment; Kramer method (visual, cephalo-caudal progression): face & neck 5-7 mg/dL (seen first in eyes), chest & upper abdomen 7-9, lower abdomen & thighs 9-11, legs/arms/forearms 11-13, palms & soles = danger sign >13-15 mg/dL (risk of kernicterus). Transcutaneous bilirubinometry (TcB): tip on skin (m/c sternum), visualizes appropriate TSB; better than visual assessment; unreliable in high bilirubin (>15 mg/dL) and preterm babies. (Book p21-22)", "qs": ["PEDS-C5-014", "PEDS-C5-015", "PEDS-C5-016", "PEDS-C5-017", "PEDS-C5-018", "PEDS-C5-019", "PEDS-C5-020", "PEDS-C5-021", "PEDS-C5-022", "PEDS-C5-023", "PEDS-C5-024", "PEDS-C5-025", "PEDS-C5-026", "PEDS-C5-027", "PEDS-C5-028", "PEDS-C5-029", "PEDS-C5-030", "PEDS-C5-031"]}, {"id": "PEDS-U043", "ch": 5, "n": 43, "title": "Types of Jaundice (Physiological vs Pathological)", "sec": "Types Of Jaundice · p22", "guide": "Table: incidence common vs less common; TSB mildly elevated vs largely elevated >15 mg/dL; rate of increase >5 mg/dL (pathological); onset usually 24-72 hrs vs <24 hrs; duration 1-2 weeks vs beyond 3-4 weeks; peak 3rd-5th day; palms & soles not affected vs affected; treatment not required (wait & watch) vs required. Any 1 positive = pathological. Note: clay/pale stools = obstruction (bile duct or intestine); conjugated bilirubin pathological if >1 mg/dL or >20% of TSB -> absorbed into blood -> urobilinogen -> dark yellow urine; cannot pass into colon -> absence of stercobilinogen -> pale/yellow stools. (Book p22)", "qs": ["PEDS-C5-032", "PEDS-C5-033", "PEDS-C5-034", "PEDS-C5-035", "PEDS-C5-036", "PEDS-C5-037", "PEDS-C5-038", "PEDS-C5-039", "PEDS-C5-040", "PEDS-C5-041", "PEDS-C5-042", "PEDS-C5-043", "PEDS-C5-044", "PEDS-C5-045", "PEDS-C5-046", "PEDS-C5-047", "PEDS-C5-048"]}, {"id": "PEDS-U044", "ch": 5, "n": 44, "title": "Causes of Jaundice", "sec": "Causes Of Jaundice · p22", "guide": "Pathological jaundice: up unconjugated bilirubin (hemolytic disorders = up breakdown of RBC e.g. hereditary spherocytosis, G6-PD deficiency; blood group incompatibility = maternal antibodies e.g. ABO/Rh; down UDPGT enzyme activity = sepsis, hypothyroidism; inherited defect of UDPGT = Crigler Najjar syndrome [Type I complete absence-severe, Type II partial absence]; extravasation of blood = cephalhemotoma) and up conjugated bilirubin (biliary atresia = obstruction of bile flow to intestine). (Book p22)", "qs": ["PEDS-C5-049", "PEDS-C5-050", "PEDS-C5-051", "PEDS-C5-052", "PEDS-C5-053", "PEDS-C5-054", "PEDS-C5-055", "PEDS-C5-056", "PEDS-C5-057", "PEDS-C5-058", "PEDS-C5-059"]}, {"id": "PEDS-U045", "ch": 5, "n": 45, "title": "Breastfeeding & Breastmilk Jaundice", "sec": "Breastfeeding Jaundice · p23", "guide": "Breast feeding jaundice: AKA suboptimal intake hyperbilirubinemia; down breast milk intake -> up enterohepatic circulation -> bilirubin re-enters liver -> up bilirubin levels; onset 5-7 days (upto 1 week); feature: excessive weight loss (>10% body weight); management: increase breastfeeding frequency and duration. Breastmilk jaundice: jaundice >3 weeks, diagnosis of exclusion; beta-glucuronidase in milk -> down conjugation -> up unconjugated bilirubin; management: continue breastfeeding, transient & self resolving. (Book p23)", "qs": ["PEDS-C5-060", "PEDS-C5-061", "PEDS-C5-062", "PEDS-C5-063", "PEDS-C5-064", "PEDS-C5-065", "PEDS-C5-066", "PEDS-C5-067", "PEDS-C5-068", "PEDS-C5-069", "PEDS-C5-070", "PEDS-C5-071"]}, {"id": "PEDS-U046", "ch": 5, "n": 46, "title": "Treatment: Normogram & Phototherapy", "sec": "Treatment of Pathological Jaundice · p23-24", "guide": "Normogram: used to decide course of treatment (serum bilirubin vs age in hours; plotted curve abnormal vs highest/normal curve). Phototherapy: blue-green LED (400-490 nm), protection of eye & gonads (testis); mechanism: a. structural isomerism (bilirubin -> lumirubin -> excreted), b. photoisomerisation (light -> bilirubin isomers), c. photooxidation; minimum irradiance 30 microwatt/cm2/nm; minimum distance 30-45 cm; terminate when at least 2 consequent values within normal curves on normogram; C/I: conjugated bilirubin (brown pigment formation -> Bronze baby syndrome). (Book p23-24)", "qs": ["PEDS-C5-072", "PEDS-C5-073", "PEDS-C5-074", "PEDS-C5-075", "PEDS-C5-076", "PEDS-C5-077", "PEDS-C5-078", "PEDS-C5-079", "PEDS-C5-080", "PEDS-C5-081", "PEDS-C5-082", "PEDS-C5-083"]}, {"id": "PEDS-U047", "ch": 5, "n": 47, "title": "Double Volume Exchange Transfusion (DVET)", "sec": "DVET · p24", "guide": "DVET indications: very high bilirubin level (abnormal in normogram); Rh isoimmunization with cord blood bilirubin >5 mg/dL or cord blood hemoglobin <10 mg/dL. Mechanism: simultaneous removal of blood with up bilirubin and replacement with equal volume of fresh blood. Amount: normal blood volume in body 80-90 mL/kg; volume exchanged 160-180 mL/kg. (Book p24)", "qs": ["PEDS-C5-084", "PEDS-C5-085", "PEDS-C5-086", "PEDS-C5-087", "PEDS-C5-088", "PEDS-C5-089", "PEDS-C5-090"]}, {"id": "PEDS-U048", "ch": 5, "n": 48, "title": "Management Protocol (Algorithm)", "sec": "Management Protocol · p24", "guide": "Newborn jaundice screening every 12 hours for 3-5 days post-birth. Serious jaundice present? d. onset <24 hours; e. yellow palms/soles; f. signs of bilirubin encephalopathy (hypertonia: opisthotonus; high pitched cry). Yes -> start phototherapy immediately + serum bilirubin testing -> plot on normogram, decide further management. No -> assess if jaundice is pathological: Yes -> serum bilirubin testing; No -> observation + followup. (Book p24)", "qs": ["PEDS-C5-091", "PEDS-C5-092", "PEDS-C5-093", "PEDS-C5-094", "PEDS-C5-095", "PEDS-C5-096", "PEDS-C5-097", "PEDS-C5-098", "PEDS-C5-099", "PEDS-C5-100", "PEDS-C5-101", "PEDS-C5-102"]}]

def q(num, sec, page, qtext, opts, ans, exp):
    assert len(opts)==4 and 0 <= ans <4
    return {"id": f"PEDS-C5-{num:03d}", "sec": sec, "page": page, "q": qtext, "opts": opts, "ans": ans, "exp": exp}

